def transform(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    border=2
    # find shape color: not bg, not border
    colors=set(cnt)-{bg,border}
    shape=colors.pop() if len(colors)==1 else None
    if shape is None:
        # multiple: pick most common non-bg
        shape=max((c for c in cnt if c not in (bg,border)), key=lambda c:cnt[c])
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==shape]
    if not cells: return g
    # find border direction: border row or column (full line of 2s)
    brow=[r for r in range(H) if all(g[r][c]==border for c in range(W))]
    bcol=[c for c in range(W) if all(g[r][c]==border for r in range(H))]
    out=[[bg]*W for _ in range(H)]
    if bcol:
        bc=bcol[0]
        # vertical border; decide side: shift shape toward border column
        if bc> max(c for _,c in cells): d=1  # border right -> move right
        else: d=-1
        # distance so that shape's far edge (toward border) touches bc-1 (or bc+1)
        if d==1: gap=bc-1-max(c for _,c in cells)
        else: gap=min(c for _,c in cells)-(bc+1)
        for r,c in cells:
            nc=c+d*gap
            out[r][max(0,min(W-1,nc))]=shape
        # line just beyond far edge of new shape
        newcols=[c for r,c in cells]
        far=(max(newcols)+d*gap) if d==1 else (min(newcols)+d*gap)
        line=far-d  # adjacent on far side
        if d==1: line=far-1
        else: line=far+1
        for r in range(H):
            if 0<=line<W and out[r][line]==bg: out[r][line]=8
    elif brow:
        bb=brow[0]
        if bb>max(r for r,_ in cells): d=1
        else: d=-1
        if d==1: gap=bb-1-max(r for r,_ in cells)
        else: gap=min(r for r,_ in cells)-(bb+1)
        for r,c in cells:
            nr=r+d*gap
            out[max(0,min(H-1,nr))][c]=shape
        newrows=[r for r,_ in cells]
        far=max(newrows)+d*gap if d==1 else min(newrows)+d*gap
        line=far-1 if d==1 else far+1
        for c in range(W):
            if 0<=line<H and out[line][c]==bg: out[line][c]=8
    else:
        return g
    # restore border
    for r in brow:
        for c in range(W): out[r][c]=border
    for c in bcol:
        for r in range(H): out[r][c]=border
    return out

